cypher:
MATCH (h:Host), (c:Container {name: h.name})
WHERE NOT EXISTS {
  (c)-[:HAS_SECRET]->()
  AND NOT EXISTS {
    (c)-[:EXPOSES]->()
    AND NOT EXISTS {
      (c)-[:DEPENDS_ON]->()
    }
  }
}
RETURN c

