MATCH (h:Host), (c:Container {name: h.name}), (p:Port {number: c.number})
WHERE NOT EXISTS((c)-[:EXPOSES]->(p))
DELETE c, p;

MATCH (c1:Container), (c2:Container)
WHERE c1.name = c2.name AND c1.id <> c2.id
DELETE c1, c2;

MATCH (h:Host), (c:Container {name: h.name})
WHERE NOT EXISTS {
  (c)-[:EXPOSES]->()
  AND (c)<-[:DEPENDS_ON]-()
}
DELETE c, h;

